import { Component, h, Prop } from '@stencil/core';

@Component({
  tag: 'std-image',
  styleUrl: 'std-image.css',
  shadow: true
})
export class StdImageComponent {
  @Prop() src: string;
  @Prop() srcTablet: string;
  @Prop() alt: string;
  @Prop() srcDesktop: string;
  @Prop() classes: string;
  @Prop() imageClasses: string;

  render() {
    const imgClasses = ['w-full h-full object-cover object-center', this.imageClasses].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <picture class={this.classes}>
        {this.srcDesktop && <source srcSet={this.srcDesktop} media="(min-width: 1024px)" />}
        {this.srcTablet && <source srcSet={this.srcTablet} media="(min-width: 768px)" />}
        <img class={imgClasses} src={this.src} alt={this.alt} />
      </picture>
    );
  }
}
